package com.coraline.feast;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.item.*;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.gametest.*;

@GameTestHolder("coraline") @PrefixGameTestTemplate(false)
public final class TreasureHuntGameTests {
    @GameTest(template="empty") public static void thousandRoutesAndAccurateFacts(GameTestHelper h){var distinct=new HashSet<String>();for(int i=0;i<1000;i++){var route=TreasureRoute.generate(i);TreasureRoute.validate(route);distinct.add(Arrays.toString(route));for(int stage=0;stage<6;stage++){String clue=TreasureRoute.clue(route,stage);h.assertTrue(!clue.isBlank()&&clue.length()<320,"Clue is empty or an essay");}}h.assertTrue(distinct.size()>950,"Routes repeat too often");h.succeed();}
    @GameTest(template="empty",timeoutTicks=600) public static void huntGeometrySequenceAndPrize(GameTestHelper h){var f=ExpeditionGameTests.fixture(h,OtherMotherActivities.Activity.TREASURE_HUNT);var p=f.p();var s=f.s();var n=s.loop.expedition;TreasureHuntActivity.build(p,s,p.serverLevel(),f.c());n.putInt("Phase",1);TreasureHuntActivity.begin(p,s);h.assertTrue(n.getLong("End")-OtherMotherLoop.now(p)==6000,"Not five minutes");var route=n.getIntArray("Route");for(var m:TreasureRoute.LANDMARKS){h.assertTrue(p.level().getBlockState(m.note(f.c())).is(net.minecraft.world.level.block.Blocks.BARREL),"Missing clue object");h.assertTrue(p.level().isEmptyBlock(m.note(f.c()).above()),"Buried clue");}h.assertTrue(!TreasureHuntActivity.advance(p,s,route[1]),"Future clue accepted");var helper=net.minecraftforge.common.util.FakePlayerFactory.get(p.serverLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"HuntHelper"));h.assertTrue(!TreasureHuntActivity.advance(helper,s,route[0]),"Helper advanced owner");for(int i=0;i<5;i++){var at=TreasureRoute.LANDMARKS.get(route[i]).note(f.c());p.setPos(Vec3.atBottomCenterOf(at.south(2)));TreasureHuntActivity.interactBlock(p,at);h.assertTrue(n.getInt("Step")==i+1,"Correct clue not accepted");TreasureHuntActivity.interactBlock(p,at);h.assertTrue(n.getInt("Step")==i+1,"Duplicate clue counted");}var door=TreasureScenery.vaultDoor(f.c(),route[5]);p.setPos(Vec3.atBottomCenterOf(door.south(2)));TreasureHuntActivity.interactBlock(p,door);h.assertTrue(n.getInt("Phase")==2&&p.level().isEmptyBlock(door),"Vault did not open");var prize=p.serverLevel().getEntitiesOfClass(ScenePropEntity.class,ExpeditionActivities.bounds(f.c(),s.loop.activity),e->e.slot==780).get(0);TreasureHuntActivity.interactProp(p,s,prize);int reward=p.getInventory().countItem(Items.ENCHANTED_GOLDEN_APPLE);TreasureHuntActivity.interactProp(p,s,prize);h.assertTrue(reward==1&&p.getInventory().countItem(Items.ENCHANTED_GOLDEN_APPLE)==1&&ActivityWorld.exitReady(s),"Reward duplicated or exit missing");h.assertTrue(!p.getInventory().contains(new ItemStack(com.coraline.registry.ModItems.TREASURE_NOTE.get())),"Borrowed note retained");h.succeed();}
    @GameTest(template="empty") public static void huntTimeoutAndLateClaim(GameTestHelper h){var f=ExpeditionGameTests.fixture(h,OtherMotherActivities.Activity.TREASURE_HUNT);var n=f.s().loop.expedition;n.putInt("Phase",1);n.putIntArray("Route",TreasureRoute.generate(17));TreasureHuntActivity.begin(f.p(),f.s());n.putLong("End",OtherMotherLoop.now(f.p()));h.assertTrue(!TreasureHuntActivity.advance(f.p(),f.s(),n.getIntArray("Route")[0]),"Expired clue accepted");TreasureHuntActivity.tick(f.p(),f.s(),f.c());h.assertTrue(n.getInt("Phase")==5&&ActivityWorld.exitReady(f.s())&&f.p().isAlive(),"Timeout softlock");h.assertTrue(f.p().getInventory().countItem(Items.ENCHANTED_GOLDEN_APPLE)==0,"Timeout awarded jackpot");h.succeed();}
}
